// stream. When the sequence is found, start_shifting is set to 1, forever,
// until reset. Reset is active high synchronous.
module TopModule(
    input  clk,
    input  reset,
    input  data,
    output reg start_shifting
);
    reg [2:0] state;
    reg [2:0] next_state;
    always @(*) begin
        case (state)
            3'b000: next_state = data ? 3'b001 : 3'b000;
            3'b001: next_state = data ? 3'b010 : 3'b000;
            3'b010: next_state = data ? 3'b011 : 3'b000;
            3'b011: next_state = data ? 3'b100 : 3'b000;
            3'b100: next_state = data ? 3'b101 : 3'b000;
            3'b101: next_state = 3'b101;
            default: next_state = 3'b000;
        endcase
    end
    always @(posedge clk) begin
        if (reset) begin
            state <= 3'b000;
            start_shifting <= 1'b0;
        end else begin
            state <= next_state;
            start_shifting <= (state == 3'b101);
        end
    end
endmodule

